// مكان (بدل صورة Unsplash العامة السابقة)، لذلك تُستورَد مباشرة هنا بدل أي
// تحميل كسول — سكشن الإنارة السينمائي نفسه يبقى مستقلاً في ملفه.
import { HEADLIGHTS_PHOTO_IMG, CinematicLightsSection } from "./CinematicLights.jsx";

// نفس قائمة الفئات المستخدمة في لوحة التحكم، حتى تُصنَّف كل سيارة تُنشر من
// هناك ضمن نفس التصنيف هنا.
const CAR_CATEGORIES = ["عائلي", "رياضي", "فخم", "صيني", "أوروبي", "اقتصادي", "SUV"];

// يحوّل صف سيارة من قاعدة البيانات إلى الشكل الذي تتوقعه واجهة الموقع
// (نسخة كاملة، تُستخدم فقط عند فتح صفحة تفاصيل سيارة محددة).
function mapCarRow(row) {
  return {
    id: row.id,
    name: row.name,
    images: [row.main_image, ...(row.gallery_images || [])].filter(Boolean),
    price: Number(row.price_per_day) || 0,
    category: row.category || "",
    type: row.category || "",
    fuel: row.fuel_type || "",
    gearbox: row.gear_type || "",
    engine_type: row.engine_type || "",
    seats: row.seats,
    year: row.year,
    horsepower: row.horsepower,
    color: row.color || "",
    mileage_km: row.mileage_km,
    description: row.description || "",
    status: row.available ? "available" : "booked",
  };
}

// نسخة خفيفة تُستخدم فقط لعرض شبكة الأسطول (بطاقات السيارات) — بدون معرض
// الصور الإضافي (gallery_images) أو الوصف أو المواصفات التفصيلية، لأن هذه
// الحقول غير مستخدَمة إلا داخل صفحة تفاصيل سيارة واحدة بعد فتحها. هذا يقلّص
// حجم أول طلب بيانات بشكل كبير فيسرّع ظهور الأسطول عند فتح الموقع.
function mapCarRowLight(row) {
  return {
    id: row.id,
    name: row.name,
    images: [row.main_image].filter(Boolean),
    price: Number(row.price_per_day) || 0,
    category: row.category || "",
    type: row.category || "",
    status: row.available ? "available" : "booked",
  };
}

// يجلب أسطول السيارات الحقيقي التابع لهذه الوكالة من Supabase — بأعمدة
// شبكة العرض فقط (خفيف وسريع).
async function getCars() {
  const { data, error } = await supabase
    .from("cars")
    .select("id, name, main_image, price_per_day, category, available, created_at")
    .eq("agency_id", AGENCY_ID)
    .order("created_at", { ascending: false });
  if (error) throw error;
  return (data || []).map(mapCarRowLight);
}

// يجلب كل بيانات سيارة واحدة (المعرض الكامل + المواصفات + الوصف) — يُستدعى
// فقط عند فتح صفحة تفاصيل تلك السيارة تحديدًا، وليس عند تحميل الأسطول كله.
async function getCarDetails(carId) {
  const { data, error } = await supabase
    .from("cars")
    .select("*")
    .eq("id", carId)
    .single();
  if (error) throw error;
  return mapCarRow(data);
}

// ينشئ طلب حجز حقيقيًا في قاعدة البيانات، بعد التحقق من توفر السيارة وعدم
// تعارض التواريخ مع أي حجز آخر قيد الانتظار أو مؤكَّد على نفس السيارة.
async function createBooking({ fullName, phone, wilaya, carId, startDate, endDate }) {
  const { data: car, error: carError } = await supabase
    .from("cars")
    .select("id, name, price_per_day, available")
    .eq("id", carId)
    .single();
  if (carError || !car) {
    throw new Error("تعذر العثور على السيارة المختارة، حاول تحديث الصفحة.");
  }
  if (!car.available) {
    throw new Error("السيارة غير متاحة حاليًا.");
  }

  const { data: existing, error: existingError } = await supabase
    .from("bookings")
    .select("id, start_date, end_date, status")
    .eq("car_id", carId)
    .in("status", ["pending", "confirmed"]);
  if (existingError) throw existingError;

  const s = new Date(startDate);
  const e = new Date(endDate);
  const overlaps = (existing || []).some(
    (b) => s <= new Date(b.end_date) && e >= new Date(b.start_date)
  );
  if (overlaps) {
    throw new Error("السيارة غير متاحة في هذه الفترة.");
  }

  const days = Math.max(1, Math.round((e - s) / 86400000));
  const total_price = days * (Number(car.price_per_day) || 0);
  // NOTE: intentionally not chaining .select() here. The public/anon role
  // has no SELECT policy on `bookings` (customers' bookings are private),
  // and Postgres enforces RLS on the RETURNING clause of INSERT too — with
  // no SELECT policy to satisfy, the whole insert gets rejected with a
  // "new row violates row-level security policy" error even though the
  // INSERT itself was allowed. We already have every field we need
  // locally, so just report success from what we sent instead of asking
  // the server to hand the (private) row back to us.
  const { error: insertError } = await supabase.from("bookings").insert({
    car_id: carId,
    customer_name: fullName,
    phone,
    wilaya,
    start_date: startDate,
    end_date: endDate,
    total_price,
    status: "pending",
  });
  if (insertError) throw insertError;

  return { car_name: car.name, total_price };
}

// يجلب روابط فيسبوك وإنستغرام الحقيقية الخاصة بالوكالة.
async function getSocialLinks() {
  const { data, error } = await supabase
    .from("agencies")
    .select("facebook_url, instagram_url")
    .eq("id", AGENCY_ID)
    .single();
  if (error || !data) return { facebook_url: "", instagram_url: "" };
  return { facebook_url: data.facebook_url || "", instagram_url: data.instagram_url || "" };
}

