const LANG_LABELS = { ar: "AR", fr: "FR", en: "EN" };
const LangContext = React.createContext({ lang: "ar", t: UI_TEXT.ar, setLang: () => {} });
function useLang() {
  return React.useContext(LangContext);
}
function LangProvider({ children }) {
  const [lang, setLang] = useState("ar");
  return (
    <LangContext.Provider value={{ lang, t: UI_TEXT[lang], setLang }}>
      {children}
    </LangContext.Provider>
  );
}
function LanguageSwitch({ className = "" }) {
  const { lang, setLang } = useLang();
  const order = ["ar", "fr", "en"];
  return (
    <div className={`lang-switch ${className}`} role="group" aria-label="اللغة">
      {order.map((code) => (
        <button
          key={code}
          type="button"
          className={`lang-switch-btn ${lang === code ? "active" : ""}`}
          onClick={(e) => { fireRipple(e); setLang(code); }}
        >
          {LANG_LABELS[code]}
        </button>
      ))}
    </div>
  );
}

