// Algerian phone numbers: 9 digits (mobile without the leading 0) or
// 10 digits (with the leading 0), digits only.
function isValidPhone(value) {
  const digits = (value || "").replace(/\D/g, "");
  return digits.length === 9 || digits.length === 10;
}
