// Small "professional" click feedback: an expanding ripple inside any .btn
// or .icon-btn the user taps, before the actual action runs.
function fireRipple(e) {
  const btn = e.currentTarget;
  if (!btn) return;
  const rect = btn.getBoundingClientRect();
  const size = Math.max(rect.width, rect.height);
  const span = document.createElement("span");
  span.className = "ripple-effect";
  span.style.width = span.style.height = size + "px";
  span.style.left = (e.clientX ? e.clientX - rect.left : rect.width / 2) - size / 2 + "px";
  span.style.top = (e.clientY ? e.clientY - rect.top : rect.height / 2) - size / 2 + "px";
  btn.appendChild(span);
  setTimeout(() => span.remove(), 650);
}

/* ------------------------- REVEAL ON SCROLL ------------------------- */

function useReveal(deps) {
  const containerRef = useRef(null);
  useEffect(() => {
    const root = containerRef.current;
    if (!root) return;
    const els = root.querySelectorAll(".reveal");
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          // Toggle both ways so items fade in every time they scroll into
          // view — whether the user is scrolling down or back up — instead
          // of only once.
          e.target.classList.toggle("show", e.isIntersecting);
        });
      },
      { threshold: 0.15, rootMargin: "0px 0px -40px 0px" }
    );
    els.forEach((el) => io.observe(el));
    return () => io.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
  return containerRef;
}

// Splits text into characters that fade in one after another, fast and
// smooth, so headline text visibly "types itself in" the instant it enters
// the screen (page load, or first scroll reveal).
function TypeFade({ text, as: Tag = "span", className = "", startDelayMs = 0, speedMs = 18 }) {
  const chars = String(text).split("");
  return (
    <Tag className={`type-fade ${className}`} aria-label={text}>
      {chars.map((ch, i) => (
        <span
          key={i}
          className="type-fade-char"
          style={{ animationDelay: `${startDelayMs + i * speedMs}ms` }}
          aria-hidden="true"
        >
          {ch === " " ? "\u00A0" : ch}
        </span>
      ))}
    </Tag>
  );
}

