/* ------------------------------ GALLERY ------------------------------ */

function Gallery({ images, name }) {
  const [index, setIndex] = useState(0);
  const [dragX, setDragX] = useState(0);
  const startX = useRef(null);
  const dragging = useRef(false);
  const trackWidth = useRef(0);
  const wrapRef = useRef(null);

  const onTouchStart = (e) => {
    startX.current = e.touches[0].clientX;
    dragging.current = true;
    trackWidth.current = wrapRef.current ? wrapRef.current.offsetWidth : 1;
  };
  const onTouchMove = (e) => {
    if (!dragging.current) return;
    const dx = e.touches[0].clientX - startX.current;
    setDragX(dx);
  };
  const endDrag = () => {
    if (!dragging.current) return;
    dragging.current = false;
    const threshold = trackWidth.current * 0.18;
    if (dragX < -threshold && index < images.length - 1) {
      setIndex((i) => i + 1);
    } else if (dragX > threshold && index > 0) {
      setIndex((i) => i - 1);
    }
    setDragX(0);
  };

  const pct = (index * 100 * -1) + (dragX / (trackWidth.current || 1)) * 100;

  return (
    <div className="gallery">
      <div
        className="gallery-track-wrap"
        ref={wrapRef}
        dir="ltr"
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={endDrag}
      >
        <div
          className="gallery-track"
          style={{
            transform: `translateX(${pct}%)`,
            transition: dragging.current ? "none" : "transform 0.4s cubic-bezier(.22,.61,.36,1)",
          }}
        >
          {images.map((src, i) => (
            <div className="gallery-slide" key={i}>
              <img src={src} alt={`${name} ${i + 1}`} draggable={false} />
            </div>
          ))}
        </div>
        {index > 0 && (
          <button
            className="gallery-nav prev"
            onClick={() => setIndex((i) => Math.max(0, i - 1))}
            aria-label="السابق"
          >
            <ChevronRight size={20} />
          </button>
        )}
        {index < images.length - 1 && (
          <button
            className="gallery-nav next"
            onClick={() => setIndex((i) => Math.min(images.length - 1, i + 1))}
            aria-label="التالي"
          >
            <ChevronLeft size={20} />
          </button>
        )}
      </div>
      <div className="gallery-dots">
        {images.map((_, i) => (
          <button
            key={i}
            className={`gallery-dot ${i === index ? "active" : ""}`}
            onClick={() => setIndex(i)}
            aria-label={`صورة ${i + 1}`}
          />
        ))}
      </div>
    </div>
  );
}

