function BookingPage({ cars, preselectedId, onDone }) {
  const availableCars = cars.filter((c) => c.status === "available");
  const [carId, setCarId] = useState(
    preselectedId && cars.find((c) => c.id === preselectedId)?.status === "available"
      ? preselectedId
      : availableCars[0]?.id || ""
  );

  if (availableCars.length === 0) {
    return (
      <div className="booking-page">
        <h1 className="booking-title">إتمام الحجز</h1>
        <p style={{ textAlign: "center", padding: "30px 0" }}>
          لا توجد سيارات متاحة للحجز حاليًا. يرجى المحاولة لاحقًا أو التواصل معنا مباشرة عبر واتساب.
        </p>
      </div>
    );
  }

  return <BookingForm cars={cars} availableCars={availableCars} initialCarId={carId} onDone={onDone} />;
}

function BookingForm({ cars, availableCars, initialCarId, onDone }) {
  const [carId, setCarId] = useState(initialCarId);
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [wilaya, setWilaya] = useState("");
  const [phone, setPhone] = useState("");
  const [phoneTouched, setPhoneTouched] = useState(false);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [serverBooking, setServerBooking] = useState(null);

  const selectedCar = cars.find((c) => c.id === carId);
  const fullName = `${firstName.trim()} ${lastName.trim()}`.trim();

  const phoneDigits = phone.replace(/\D/g, "");
  const phoneError =
    phoneTouched && phoneDigits.length > 0 && !isValidPhone(phone)
      ? "رقم الهاتف غير صحيح يجب أن يتكون من 9 أو 10 أرقام."
      : "";

  const days = (() => {
    if (!startDate || !endDate) return 0;
    const s = new Date(startDate);
    const e = new Date(endDate);
    const diff = Math.round((e - s) / 86400000);
    return diff > 0 ? diff : 0;
  })();

  const total = selectedCar && days > 0 ? days * selectedCar.price : 0;

  const allFieldsFilled = Boolean(
    firstName.trim() && lastName.trim() && wilaya && phone.trim() && carId && startDate && endDate
  );

  const handleSubmit = async (e) => {
    e.preventDefault();
    setPhoneTouched(true);
    if (!firstName.trim() || !lastName.trim() || !wilaya || !phone.trim() || !carId || !startDate || !endDate) {
      setError("الرجاء تعبئة جميع الحقول.");
      return;
    }
    if (!isValidPhone(phone)) {
      setError("رقم الهاتف غير صحيح يجب أن يتكون من 9 أو 10 أرقام.");
      return;
    }
    if (days <= 0) {
      setError("تاريخ النهاية يجب أن يكون بعد تاريخ البداية.");
      return;
    }
    setError("");
    setSubmitting(true);
    try {
      const booking = await createBooking({
        fullName,
        phone: phone.trim(),
        wilaya,
        carId,
        startDate,
        endDate,
      });
      setServerBooking(booking);
      setSubmitted(true);
    } catch (err) {
      // e.g. "السيارة غير متاحة في هذه الفترة." raised by the database itself
      setError(err.message || "تعذر إتمام الحجز حاول مجددًا.");
    } finally {
      setSubmitting(false);
    }
  };

  if (submitted && selectedCar) {
    return (
      <div className="success-page">
        <div className="success-icon">
          <CheckCircle2 size={56} />
        </div>
        <h2>تم إرسال طلب الحجز بنجاح</h2>
        <p className="success-sub">سيتصل بك فريقنا خلال دقائق لتأكيد الحجز.</p>

        <div className="success-card">
          <div className="success-row">
            <span>السيارة</span>
            <strong>{selectedCar.name}</strong>
          </div>
          <div className="success-row">
            <span>الاسم الكامل</span>
            <strong>{fullName}</strong>
          </div>
          <div className="success-row">
            <span>الولاية</span>
            <strong>{wilaya}</strong>
          </div>
          <div className="success-row">
            <span>رقم الهاتف</span>
            <strong dir="ltr">{phone}</strong>
          </div>
          <div className="success-row">
            <span>من</span>
            <strong>{startDate}</strong>
          </div>
          <div className="success-row">
            <span>إلى</span>
            <strong>{endDate}</strong>
          </div>
          <div className="success-row">
            <span>عدد الأيام</span>
            <strong>{days} يوم</strong>
          </div>
          <div className="success-row total">
            <span>المبلغ الإجمالي</span>
            <strong>
              {Number(serverBooking?.total_price ?? total).toLocaleString("en-US")} دج
            </strong>
          </div>
        </div>

        <p className="success-sub" style={{ marginBottom: 20 }}>
          حالة الطلب: قيد الانتظار — ستتلقى تأكيدًا نهائيًا عبر الهاتف.
        </p>

        <button className="btn btn-primary btn-block" onClick={(e) => { fireRipple(e); onDone(); }}>
          العودة إلى الرئيسية
        </button>
      </div>
    );
  }

  return (
    <div className="booking-page">
      <h1 className="booking-title">إتمام الحجز</h1>
      <p className="booking-sub">
        عبّئ المعلومات التالية وسنتواصل معك لتأكيد الحجز.
      </p>

      <form className="booking-form" onSubmit={handleSubmit}>
        <div className="field-row">
          <label className="field">
            <span>الاسم</span>
            <div className="field-input">
              <User size={16} />
              <input
                type="text"
                placeholder="مثال: أحمد"
                value={firstName}
                onChange={(e) => setFirstName(e.target.value)}
                required
              />
            </div>
          </label>
          <label className="field">
            <span>اللقب</span>
            <div className="field-input">
              <User size={16} />
              <input
                type="text"
                placeholder="مثال: بن علي"
                value={lastName}
                onChange={(e) => setLastName(e.target.value)}
                required
              />
            </div>
          </label>
        </div>

        <label className="field">
          <span>الولاية</span>
          <div className="field-input">
            <MapPin size={16} />
            <select value={wilaya} onChange={(e) => setWilaya(e.target.value)} required>
              <option value="" disabled>
                اختر ولايتك
              </option>
              {WILAYAS.map((w) => (
                <option key={w} value={w}>
                  {w}
                </option>
              ))}
            </select>
          </div>
        </label>

        <label className="field">
          <span>رقم الهاتف</span>
          <div className={`field-input ${phoneError ? "field-input-error" : ""}`} dir="ltr">
            <Phone size={16} />
            <input
              type="tel"
              placeholder="+213 5XX XX XX XX"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              onBlur={() => setPhoneTouched(true)}
              required
            />
          </div>
          {phoneError && <span className="field-error-text">{phoneError}</span>}
        </label>

        <label className="field">
          <span>السيارة المختارة</span>
          <div className="field-input">
            <Car size={16} />
            <select value={carId} onChange={(e) => setCarId(e.target.value)}>
              {availableCars.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.name} — {c.price.toLocaleString("en-US")} دج/يوم
                </option>
              ))}
            </select>
          </div>
        </label>

        <div className="field-row">
          <label className="field">
            <span>تاريخ البداية</span>
            <div className="field-input">
              <Calendar size={16} />
              <input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
              />
            </div>
          </label>
          <label className="field">
            <span>تاريخ النهاية</span>
            <div className="field-input">
              <Calendar size={16} />
              <input
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
              />
            </div>
          </label>
        </div>

        {selectedCar && (
          <div className="price-summary">
            <div className="price-summary-row">
              <span>سعر اليوم</span>
              <strong>{selectedCar.price.toLocaleString("en-US")} دج</strong>
            </div>
            <div className="price-summary-row">
              <span>عدد الأيام</span>
              <strong>{days} يوم</strong>
            </div>
            <div className="price-summary-row total">
              <span>الإجمالي</span>
              <strong>{total.toLocaleString("en-US")} دج</strong>
            </div>
          </div>
        )}

        {error && <div className="form-error">{error}</div>}

        <button
          type="submit"
          className="btn btn-primary btn-block"
          disabled={submitting || !allFieldsFilled || Boolean(phoneError)}
          onClick={fireRipple}
        >
          {submitting ? "جارٍ الإرسال..." : "تأكيد الحجز"}
        </button>
      </form>
    </div>
  );
}

